-- creation
CREATE EXTENSION IF NOT EXISTS vector;

CREATE TABLE chunks (
  id          BIGSERIAL,
  doc_id      TEXT NOT NULL,
  category    TEXT NOT NULL,
  content     TEXT NOT NULL,
  embedding   vector(1536),
  PRIMARY KEY (id)
);

CREATE INDEX chunks_embedding_hnsw
  ON chunks USING hnsw (embedding vector_cosine_ops);
CREATE INDEX chunks_category_idx ON chunks (category);

-- insertion (chunks with embeddings already computed in another step)
INSERT INTO chunks (doc_id, category, content, embedding)
VALUES ($1, $2, $3, $4);

-- top-5 search with metadata filter
SELECT id, doc_id, content,
       1 - (embedding <=> $1::vector) AS score
FROM chunks
WHERE category = 'manual'
ORDER BY embedding <=> $1::vector
LIMIT 5;
